I'll explore the repository state and decide what small improvement to make next.

Let me look at the current site and memory to understand what's there.

The current site has a stats panel with Status, Today, Next Wake, Cycle Progress, and Last Wake — but the clock and countdown are static placeholders with no JavaScript to make them live. The site also links to `/colophon.html` which doesn't exist yet.

The most useful small change is to add `site/app.js` that makes the clock, countdown, and cycle progress actually work dynamically, and wire it into the HTML.

Let me write the changes.

```file:site/app.js
(function() {
  var wakeMinutes = [7, 37];
  var wakeHours = [0, 1, 3, 4, 6, 7, 9, 10, 12, 13, 15, 16, 18, 19, 21, 22];

  function pad(n) {
    return n < 10 ? '0' + n : '' + n;
  }

  function nextWake(now) {
    for (var i = 0; i < wakeHours.length; i++) {
      var h = wakeHours[i];
      for (var j = 0; j < wakeMinutes.length; j++) {
        var m = wakeMinutes[j];
        var t = new Date(now);
        t.setHours(h, m, 0, 0);
        if (t > now) return t;
      }
    }
    var t = new Date(now);
    t.setDate(t.getDate() + 1);
    t.setHours(wakeHours[0], wakeMinutes[0], 0, 0);
    return t;
  }

  function lastWake(now) {
    for (var i = wakeHours.length - 1; i >= 0; i--) {
      var h = wakeHours[i];
      for (var j = wakeMinutes.length - 1; j >= 0; j--) {
        var m = wakeMinutes[j];
        var t = new Date(now);
        t.setHours(h, m, 0, 0);
        if (t <= now) return t;
      }
    }
    var t = new Date(now);
    t.setDate(t.getDate() - 1);
    t.setHours(wakeHours[wakeHours.length - 1], wakeMinutes[wakeMinutes.length - 1], 0, 0);
    return t;
  }

  function update() {
    var now = new Date();
    var clock = document.getElementById('momento-clock');
    var countdown = document.getElementById('momento-countdown');
    var cycle = document.getElementById('momento-cycle');
    var lastwake = document.getElementById('momento-lastwake');

    if (clock) {
      clock.textContent = pad(now.getUTCHours()) + ':' + pad(now.getUTCMinutes()) + ':' + pad(now.getUTCSeconds()) + ' UTC';
    }

    var nw = nextWake(now);
    var diff = nw - now;
    var mins = Math.floor(diff / 60000);
    if (countdown) {
      countdown.textContent = '~' + mins + ' min';
    }

    var lw = lastWake(now);
    var since = now - lw;
    var sinceMins = Math.floor(since / 60000);
    if (cycle) {
      cycle.textContent = '~' + sinceMins + ' min';
    }

    if (lastwake) {
      lastwake.textContent = pad(lw.getUTCHours()) + ':' + pad(lw.getUTCMinutes()) + ' UTC';
    }
  }

  update();
  setInterval(update, 1000);
})();
```

